SELECT id, active_id, share_user_id, share_username, share_user_phone, invitation_time, register_user_id, register_username, register_user_phone, order_no FROM sys_active_record WHERE active_id = #{param.activeId}
AND (share_username LIKE concat('%', #{param.nameOrPhone},'%') OR share_user_phone LIKE concat('%',#{param.nameOrPhone},'%') OR register_username LIKE concat('%',#{param.nameOrPhone},'%') OR register_user_phone LIKE concat('%',#{param.nameOrPhone},'%'))
AND invitation_time >= #{param.startDay}
AND invitation_time <= #{param.endDay}
order by invitation_time desc

SELECT id, active_id, share_user_id, share_username, share_user_phone, invitation_time, register_user_id, register_username, register_user_phone, order_no FROM sys_active_record WHERE active_id = #{param.activeId}
AND (register_username LIKE concat('%',#{param.nameOrPhone},'%') OR register_user_phone LIKE concat('%',#{param.nameOrPhone},'%'))
order by invitation_time desc
